const item = $input.first().json;
const body = item.body || item;
const query = item.query || {};

const rawDate = body.leaveDate || body.leave_date || '';
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ 
  json: {
    token: body.token || query.token || '',
    action: body.action || query.action || 'approve',
    employeeName: body.employeeName || body.employee_name || '',
    employeeEmail: body.employeeEmail || body.employee_email || '',
    leaveDate: rawDate,
    leaveDateDisplay: fmt(rawDate),
  endDateDisplay: fmt(body.end_date || body.endDate || ''),
    leaveDays: parseInt(body.leaveDays || body.leave_days || 0),
    leaveId: body.leaveId || '',
    reason: body.reason || '',
    department: body.department || '',
    requiresHrApproval: body.requiresHrApproval === true || body.requiresHrApproval === 'true',
    hrApprovalLink: body.hrApprovalLink || body.hrApproval_link || '',
    hrEmail: body.hrEmail || body.hr_email || '',
    managerEmail: body.managerEmail || '',

    // DÒNG QUAN TRỌNG: Lấy Token từ Webhook để chuyển cho node sau pha chế
    hrApprovalToken: body.hrApprovalToken || '', 

    managerApprovalLink: body.managerApprovalLink || body.manager_approval_link || '',
    isInternalCall: body.isInternalCall === true || body.isInternalCall === 'true',
    backendUrl: 'http://backend:3001' + '/api/approval/manager'
  } 
}];

const resp = $input.first().json;
const data = resp.body || resp;
const input = $('Parse Input').first().json;

const frontendUrl = 'https://approvehub.internalautomation.io.vn';

const msg = data.message || '';
const isAlreadyProcessed = (resp.statusCode === 400 || resp.statusCode === 409) &&
  (msg.includes('da duoc xu ly') || msg.includes('already processed'));

const effectiveRequiresHr = isAlreadyProcessed
  ? (input.requiresHrApproval === true ? true : input.requiresHrApproval)
  : input.requiresHrApproval;

const hrToken = data.hrApprovalToken || input.hrApprovalToken || '';
const hrApprovalLink = hrToken ? frontendUrl + '/approval-page.html?token=' + encodeURIComponent(hrToken) + '&hr=true' : (input.hrApprovalLink || '');
const rawDate = input.leaveDate || '';

// LẤY GIÁ TRỊ END DATE TỪ INPUT ĐỂ FIX LỖI
const endDateComputed = input.endDateDisplay || ''; 

const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  // Nếu là định dạng dd/mm/yyyy thì pd sẽ là NaN, hàm này sẽ trả về nguyên gốc chuỗi đó
  if (isNaN(pd)) return d; 
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ 
  json: {
    success: resp.statusCode === 200 || isAlreadyProcessed,
    status: isAlreadyProcessed
      ? (input.action === 'reject' ? 'rejected' : 'approved')
      : (data.status || ''),
    action: input.action,
    message: isAlreadyProcessed ? 'Already processed via email link' : (data.message || ''),
    leaveId: data.leaveId || input.leaveId || '',
    employeeName: input.employeeName,
    employeeEmail: input.employeeEmail,
    leaveDate: rawDate,
    leaveDateDisplay: fmt(rawDate),
    // Dòng 48 hiện tại đã có biến để gọi:
    endDateDisplay: fmt(endDateComputed), 
    leaveDays: input.leaveDays,
    reason: input.reason,
    department: input.department,
    requiresHrApproval: effectiveRequiresHr,
    hrApprovalLink: hrApprovalLink,
    hrEmail: data.hrEmail || input.hrEmail,
  } 
}];

